["Bring twenty-four Robo-mechanical Guts to Shoni in Stormwind."]="收集24副機械內膽，把它們交給暴風城的舒尼。",
["Brohann Caskbelly in Stormwind wants you to search for the Temple of Atal'Hakkar."]="暴風城的布羅哈恩·鐵桶要求妳去找到阿塔哈卡神廟。",
["Capture the spirits of 3 screechers in Feralas, then return to Yeh'kinya in Steamwheedle Port."]="在菲拉斯捕獲3個尖嘯者的靈魂，然後回到熱砂港的葉基亞那裏去。",
["Check the cages at the two Witherbark villages, then return to Gryphon Master Talonaxe."]="檢查兩個枯木巨魔村落裏的籠子，然後向獅鷲管理員沙拉克·鷹斧回復。",
["Check the top of the Altar of Zul, then return to Gryphon Master Talonaxe."]="檢查祖爾祭壇的頂部，然後向獅鷲管理員沙拉克·鷹斧報告。",
["Collect 10 Shadowshard Fragments from Maraudon and return them to Archmage Tervosh in Theramore on the coast of Dustwallow Marsh."]="從瑪拉頓收集10塊暗影殘片，然後把它們交給塵泥沼澤塞拉摩島上的大法師特沃什。",
["Collect 10 Shadowshard Fragments from Maraudon and return them to Uthel'nay in Orgrimmar."]="從瑪拉頓收集10塊暗影殘片，然後把它們交給奧格瑞瑪的尤塞爾奈。",
["Collect 15 Bloodpetals and return to Muigin."]="從安戈洛爾環形山的血瓣花猛擊者和血瓣花掠奪者身上收集15個血瓣花，然後向穆爾金回復。",
["Collect 15 Theradric Crystal Carvings for Willow in Desolace."]="為淒涼之地的維洛收集25個瑟萊德絲水晶雕像。",
["Collect 20 Fetishes of Hakkar and bring them to Fel'Zerul in Stonard."]="收集20個哈卡神像，把它們帶給斯通納德的費澤魯爾。",
["Collect 20 Minion's Scourgestones and bring them to High Priest Thel'danis in the Western Plaguelands."]="收集20個爪牙的天災石，並將它們交給西瘟疫之地的高階牧師賽爾丹尼斯。",
["Collect 4 Hearts of Flame and 4 globes of Golem Oil and return the items to Kalaran Windblade."]="收集4份烈焰之心和4份傀儡之油，然後把這些東西交給卡拉然·溫布雷。",
["Collect 5 samples of Atal'ai Haze, then return to Muigin in Un'Goro Crater."]="收集5份阿塔萊之霧的樣本，然後向安戈洛環形山的穆爾金復命。",
["Collect 6 Enchanted Coral and return them to Archmage Xylem."]="收集6塊魔化珊瑚，然後把它們交給大法師克希雷姆。",
["Collect 8 Bloodcap and 8 Gorishi Stings, and return to Torwa Pathfinder in Un'Goro Crater."]="收集壹些血帽和格裏什釘刺，然後向托爾瓦·尋路者復命。",
["Collect a sample of air, fire, earth and water for Bath'rah the Windwatcher."]="為捕風者巴斯拉收集壹份空氣樣本、壹份火元素樣本、壹份土元素樣本和壹份水元素樣本。",
["Confront Ulathek, then bring The Traitor's Heart to Lord Banehollow in Jaedenar."]="找到並殺死烏拉泰克，然後把叛徒之心交給加德納爾的魔王貝恩霍勒。",
["Councilman Millstipe of Darkshire wants you to bring him the hand of Dextren Ward."]="夜色鎮的米爾斯迪普議員要妳殺死迪克斯特·瓦德，並把他的手帶回來作為證明。",
["Crane Operator Bigglefuzz in Ratchet wants you to retrieve the bottle of 99-Year-Old Port from Mad Magglish who is hiding in the Wailing Caverns."]="棘齒城的起重機操作員比戈弗茲讓妳從瘋狂的馬格利什那兒取回壹瓶99年波爾多陳釀，瘋狂的馬格利什就藏在哀嚎洞穴裏。",
["Defend Gor'shak."]="保護哥沙克。",
["Deliver Rexxar's Letter to Myranda the Hag in the Western Plaguelands."]="把雷克薩的證明交給西瘟疫之地的巫女麥蘭達。",
["Deliver the Letter to the City Architect to Baros Alexston in Stormwind."]="將艾德溫·範克裏夫的信交給巴隆斯·阿歷克斯頓。",
["Deliver the Unloaded Zapper and 5 samples of Atal'ai Haze to Larion in Marshal's Refuge."]="收集5份阿塔萊之霧的樣本，然後將它們送到馬紹爾營地的拉瑞安那裏。",
["Destroy 30 Undead Ravagers, then return to Brother Anton at Nijel's Point."]="殺掉30個亡靈劫掠者，然後向尼耶爾前哨站的安東修士復命。",
["Destroy Araj the Summoner and bring Araj's Scarab to Alchemist Arbington at Chillwind Point, Western Plaguelands."]="殺掉召喚者阿拉基，並將阿拉基的聖甲蟲交給西瘟疫之地冰風崗的化學家阿爾比頓。",
["Destroy Araj the Summoner and bring Araj's Scarab to Apothecary Dithers at the Bulwark, Western Plaguelands."]="殺掉召喚者阿拉基，並將阿拉基的聖甲蟲交給西瘟疫之地亡靈壁壘的藥劑師迪瑟斯。",
["Destroy the drake champion of the Green Flight, Somnus. Take his skull and return it to Emberstrife."]="殺掉綠龍索姆努斯，把他的顱骨交給埃博斯塔夫。",
["Ebru in the Wailing Caverns wants you to kill 7 Deviate Ravagers, 7 Deviate Vipers, 7 Deviate Shamblers and 7 Deviate Dreadfangs."]="哀嚎洞穴的厄布魯要求妳殺掉7只變異破壞者、7只劇毒飛蛇、7只變異蹣跚者和7只變異尖牙風蛇。",
["Enter Ragefire Chasm and slay Taragaman the Hungerer, then bring his heart back to Neeru Fireblade in Orgrimmar."]="進入怒焰裂谷，殺死饑餓者塔拉加曼，然後把他的心臟交給奧格瑞瑪的尼爾魯·火刃。",
["Escort Kernobee to the Clockwerk Run exit and then report to Scooty in Booty Bay."]="將克努比護送到出口，然後向藏寶海灣的斯庫提匯報。",
["Escort Willix the Importer out of Razorfen Kraul."]="護送進口商威利克斯逃出剃刀沼澤。",
["Escort the Defias Traitor to the secret hideout of the Defias Brotherhood. Once the Defias Traitor shows you where VanCleef and his men are hiding out, return to Gryan Stoutmantle with the information."]="護送迪菲亞叛徒前往迪菲亞兄弟會的秘密藏身處。迪菲亞叛徒把妳帶到範克裏夫和他的手下的巢穴之後，盡快回去向格裏安·斯托曼匯報相關信息。",
["Fel'zerul in Stonard wants you to gather 10 Atal'ai Artifacts."]="斯通納德的費澤魯爾要求妳收集10件阿塔萊神器。",
["Figure out a way to remove the grime from the Grime-Encrusted Ring."]="想方法把臟兮兮的戒指弄幹凈。",
["Find 3 Soran'ruk Fragments and 1 Large Soran'ruk Fragment and return them to Doan Karhan in the Barrens."]="找到3塊索蘭魯克寶珠的碎片和1塊索蘭魯克寶珠的大碎片，把它們交給貧瘠之地的杜安·卡漢。",
["Find Advisor Belgrum and give him his note."]="找到顧問貝爾格拉姆，把便箋交給他。",
["Find Agmond."]="找到阿戈莫德。",
["Find Baelog in Uldaman."]="在奧達曼找到巴爾洛戈。",
["Find Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains."]="找到連接石爪山和灰谷的石爪小徑裏的布勞格·幽魂。",
["Find Daphne Stilwell in Westfall."]="在西部荒野找到達芙妮·斯迪威爾。",
["Find Egan. You only know that he was last seen around Stratholme."]="找到埃根。妳只知道他在斯坦索姆附近。",
["Find Hammertoe Grez in Uldaman."]="在奧達曼找到鐵趾格雷茲。",
["Find Hammertoe's Amulet and return it to him in Uldaman."]="找到鐵趾的護符，把它交給奧達曼的鐵趾。",
["Find Lord Incendius in Blackrock Depths and destroy him!"]="在黑石深淵裏找到伊森迪奧斯，然後把他幹掉！",
["Find Magma Lord Bokk in the Burning Steppes, obtain his Magma Core and bring it to Mux Manascrambler in Gadgetzan."]="去燃燒平原找到熔岩領主博克，取得他的岩漿之核帶給在加基森的莫克斯·法力爭奪者。",
["Find Marvon Rivetseeker in Tanaris."]="到塔納利斯找到瑪爾馮·瑞文斯克。",
["Find Parqual Fintallas in Undercity."]="找到幽暗城的帕科瓦·芬塔拉斯。",
["Find Prate Cloudseer in Thousand Needles."]="到千針石林去找普拉特·白雲。",
["Find Prospector Ryedol and let him know Hammertoe Grez is alive."]="找到勘察員雷杜爾，告訴他鐵趾格雷茲還活著。",
["Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke."]="在通靈學院裏找到萊斯·霜語。當妳找到他之後，使用禁錮靈魂的遺物破除其亡靈的外殼。如果妳成功地破除了他的不死之身，就殺掉他並拿到萊斯·霜語的頭顱。把那個頭顱交給馬杜克鎮長。",
["Find Starfall in Winterspring and speak with Wynd Nightchaser."]="找到冬泉谷的墜星村，在那裏與維恩德·夜風談壹談。",
["Find The Beginnings of the Undead Threat, and return it to Parqual Fintallas in Undercity."]="找到《亡靈的起源》，把它交給幽暗城的帕科瓦·芬塔拉斯。",
["Find a clue as to the gems' whereabouts in the depths of Uldaman."]="在奧達曼裏找尋寶石的線索。",
["Find and return Treshala's Pendant to Treshala Fallowbrook in Darnassus."]="將塔莎拉的墜飾帶給達納蘇斯的塔莎拉·靜水。",
["Find and return a Symbol of Ragnaros to Kalaran Windblade."]="找到壹個拉格納羅斯符記，把它交給卡拉然·溫布雷。",
["Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic."]="找到並殺掉傀儡統帥阿格曼奇，將他的頭交給魯特維爾。妳還需要從守衛著阿格曼奇的狂怒傀儡和戰鬥傀儡身上收集10塊完整的元素核心。",
["Find someone who can translate the paladin's journal. The closest location that might have someone is Kargath, in the Badlands."]="在荒蕪之地的卡加斯哨所裏尋找壹個可以幫妳翻譯聖騎士日記的人。",
["Find the 4 tablets and bring their legends back to Brother Nimetz."]="找到4塊石板並將上面的內容帶回去交給尼麥茲修士。",
["Find the Altar of Hakkar in the Sunken Temple in Swamp of Sorrows."]="在悲傷沼澤沈沒的神廟中找到哈卡祭壇。",
["Find the Black Guard Swordsmith in Stratholme and destroy him. Recover the Insignia of the Black Guard and return to Seril Scourgebane."]="在斯坦索姆找到黑衣守衛鑄劍師，然後殺死他。將黑色衛士徽記交給亡靈殺手瑟裏爾。",
["Find the Deathstalker Adamant and Deathstalker Vincent."]="找到亡靈哨兵阿達曼特和亡靈哨兵文森特。",
["Find the Felvine in Dire Maul and acquire a shard from it. Chances are you'll only be able to procure one with the demise of Alzzin the Wildshaper. Use the Reliquary of Purity to securely seal the shard inside, and return it to Rabine Saturna in Nighthaven, Moonglade."]="在厄運之槌中找到魔藤，然後從它上面采集壹塊碎片。只有幹掉了奧茲恩之後，妳才能進行采集工作。使用凈化之匣安全地封印碎片，然後將其交給月光林地永夜港的拉比恩·薩圖納。",
["Find the Legacy of the Aspects and return it to Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains."]="找到《巨龍的遺產》，把它還給位於灰谷和石爪山之間的石爪小徑裏的布勞格·幽魂。",
["Find the Sacred Highborne Writings in the Temple of Zin-Malor in Azshara, and bring them to Aurora Skycaller near the Northpass Tower in Eastern Plaguelands."]="在艾薩拉的辛瑪洛神殿裏找到神聖的上層精靈筆跡，並將它帶給位於東瘟疫之地的北地哨塔附近的奧蘿拉。",
["Find the Tablet of Will, and return them to Advisor Belgrum in Ironforge."]="找到意誌石板，把它們交給鐵爐堡的顧問貝爾格拉姆。",
["Find the traitors and recover their artifacts, then return to Magus Voidglare in Tarren Mill."]="找到被遺忘者的叛徒，取回他們偷走的神器，然後回到塔倫米爾去見大法師沃迪恩·伍德格萊爾。",
["Follow Reginald Windsor through Stormwind. Protect him from harm!"]="跟隨雷吉納德·溫德索爾元帥在暴風城中前進。保護他，別讓他受到傷害！",
["Gather 10 Atal'ai Tablets for Brohann Caskbelly in Stormwind."]="為暴風城的布羅哈恩·鐵桶收集10塊阿塔萊石板。",
["Gather 5 Intact Raptor Horns from Sunscale Scytheclaws, and bring them to Mebok Mizzyrix in Ratchet."]="從赤鱗鐮爪龍身上收集5根完整的迅猛龍角，把它們交給棘齒城的米希瑞克斯。",
["Gershala Nightwhisper in Auberdine wants 8 Corrupt Brain stems."]="奧伯丁的戈沙拉·夜語需要8塊墮落者的腦幹。",
["Get Krom Stoutarm's treasured possession from his chest in the North Common Hall of Uldaman, and bring it to him in Ironforge."]="到奧達曼的北部大廳去找到克羅姆·粗臂的箱子，從裏面拿出他的寶貴財產，然後回到鐵爐堡把東西交給他。",
["Get Patrick Garrett's family treasure from their family chest in the South Common Hall of Uldaman, and bring it to him in the Undercity."]="從奧達曼南部大廳的箱子中找到加勒特的家族寶藏，然後把它交給幽暗城的帕特裏克·加瑞特。",
["Give Marshal Maxwell the bad news."]="把這個壞消息傳達給麥克斯韋爾元帥。",
["Give Tinkee's Letter to Felnok Steelspring."]="把丁奇的信交給菲諾克。",
["Give the Dull and Flat Elven Blade to Lorekeeper Lydros."]="把黯淡的精靈劍交給博學者萊德羅斯。",
["Go into Stratholme and rescue Ysida Harmon from Baron Rivendare."]="前往斯坦索姆從瑞文戴爾男爵那裡救出亞希達·哈莫。",
["Gryan Stoutmantle wants you to talk to Wiley in Lakeshire."]="格裏安·斯托曼要求妳去和湖畔鎮的威利談壹談。",
["Guarding the Caverns of Time in the Tanaris Desert is Chronalis, child of Nozdormu. Destroy him and return his skull to Emberstrife."]="諾茲多姆的孩子克魯納裏斯在塔納利斯沙漠守衛著時光之穴。殺了他，把他的顱骨交給埃博斯塔夫。",
["Help Marshal Windsor get his gear back and free his friends. Return to Marshal Maxwell if you succeed."]="幫助溫德索爾元帥拿回他的裝備並救出他的朋友。當妳成功之後就回去向麥克斯韋爾元帥復命。",
["Hunt 5 Bloodpetal Lashers, 5 Bloodpetal Threshers, 5 Bloodpetal Flayers and 5 Bloodpetal Trappers for Larion at Marshal's Refuge."]="為馬紹爾營地裏的拉瑞安殺掉5個血瓣花鞭笞者、5個血瓣花捕獸者、5個血瓣花掠奪者和5個血瓣花猛擊者。",
["If you agree to aid Belnistrasz, speak with him again and hand the Oathstone he gave you back to him."]="如果妳同意幫助奔尼斯特拉茲，就再跟他談談，並將誓言石還給他。",
["If you are interested in helping Sagorne Crestrider in Orgrimmar's Valley of Wisdom, bring him an Azerothian Diamond and a Pristine Black Diamond."]="如果妳願意幫助奧格瑞瑪智慧谷的薩格尼，就將壹塊艾澤拉斯鉆石和壹塊原始黑鉆石交給他。",
["If you have faith, leap from the planks overlooking Thousand Needles."]="如果妳有堅定的信仰，就從那個可以俯瞰千針石林的木板跳下去。",
["In the heart of Blackrock Spire you will find Mother Smolderweb. Engage her and get her to poison you. Chances are good that you will have to kill her as well. Return to Ragged John when you are poisoned so that he can 'milk' you."]="妳可以在黑石塔的中心地帶找到煙網蛛後。與她戰鬥，讓她在妳體內註入毒汁。如果妳有能力的話，就殺死她吧。當妳中毒之後，回到狼狽不堪的約翰那兒，他會從妳的身體裏抽取這些“蛛後的乳汁”。",
["Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine."]="將臟兮兮的東西放入超級清潔器5200型，記得要用三枚銀幣來啟動機器。",
["It would appear as if the charade is over. You know that the Amulet of Draconic Subversion that Myranda the Hag created for you will not function inside Blackrock Spire. Perhaps you should find Rexxar and explain your predicament. Show him the Dull Drakefire Amulet. Hopefully he will know what to do next."]="看來這場假面舞會就要結束了。妳知道麥蘭達為妳制作的龍形護符在黑石塔裏面不會發揮作用，也許妳應該去找雷克薩，將妳的困境告訴他。把黯淡的龍火護符給他看看，也許他知道下壹步該怎麽做。",
["Kill 15 Mosshide Gnolls and 10 Mosshide Mongrels, then return to Rethiel the Greenwarden in the Wetlands."]="殺死15名蘚皮豺狼人和10名混血蘚皮豺狼人，然後向濕地的綠色守衛者雷希耶爾復命。",
["Kill 20 Plagued Hatchlings, then return to Betina Bigglezink at the Light's Hope Chapel."]="殺掉20只瘟疫龍崽，然後向聖光之願禮拜堂的貝蒂娜·比格辛克復命。",
["Kill 6 Dalaran Summoners and 12 Elemental Slaves, then return to Magus Voidglare in Tarren Mill."]="殺掉6個達拉然召喚師和12個元素奴仆，然後回到塔倫米爾去見大法師沃迪恩·伍德格萊爾。",
["Kill 7 Helboar in the Blasted Lands and return to the Fallen Hero of the Horde."]="殺死7頭地獄野豬，然後回到部落英雄的靈魂那兒。",
["Kill 8 Bleeding Horrors and 8 Wandering Spirits, then report back to Linnea at her camp."]="殺死8個可怕的血僵屍和8個遊蕩的幽靈，然後向亡靈衛兵林奈匯報。",
["Kill 8 Razorfen Battleguard, 8 Razorfen Thornweavers, and 8 Death's Head Cultists and return to Myriam Moonsinger near the entrance to Razorfen Downs."]="殺掉8個剃刀沼澤護衛者、8個剃刀沼澤織棘者和8個亡首教徒，然後向剃刀高地入口處的麥雷姆·月歌復命。",
["Kill Ambassador Infernus in Angor Fortress and bring proof of his death to Advisor Belgrum in Ironforge."]="殺死苦痛堡壘中的因弗努斯大使，把證明他已死亡的信物交給鐵爐堡的顧問貝爾格拉姆。",
["Kill Arugal and bring his head to Dalar Dawnweaver at the Sepulcher."]="殺死阿魯高，把他的頭帶給瑟伯切爾的達拉爾·道恩維沃爾。",
["Kill Bazil Thredd and bring his head back to Warden Thelwater at the Stockade."]="殺死巴基爾·斯瑞德，把他的頭帶給監獄的典獄官塞爾沃特。",
["Kill Bazzalan and Jergosh the Invoker before returning to Thrall in Orgrimmar."]="殺死巴紮蘭和祈求者耶戈什，然後回到奧格瑞瑪的薩爾那裏。",
["Kill Edwin VanCleef and bring his head to Gryan Stoutmantle."]="殺死艾德溫·範克裏夫，把他的頭交給格裏安·斯托曼。",
["Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Raleigh the Devout in Southshore."]="殺死大檢察官懷特邁恩，血色十字軍指揮官莫格萊尼，十字軍的勇士赫洛德和馴犬者洛克希並向南海鎮的萊雷恩復命。",
["Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Varimathras in the Undercity."]="殺掉大檢察官懷特邁恩、血色十字軍指揮官莫格萊尼、血色十字軍勇士赫洛德和馴犬者洛克希，然後向幽暗城的瓦裏瑪薩斯回報。",
["Kill Lorgus Jett in Blackfathom Deeps and then return to Je'neu Sancrea in Ashenvale."]="殺掉黑暗深淵裏的洛古斯·傑特，然後向灰谷的耶努薩克雷復命。",
["Kill Morphaz in the sunken temple of Atal'Hakkar, and return his blood to Greta Mosshoof in Felwood. The entrance to the sunken temple can be found in the Swamp of Sorrows."]="前往沈沒的阿塔哈卡神廟，殺死綠龍摩弗拉斯，將他的血液交給費伍德森林中的格雷塔·苔蹄。沈沒的神廟的入口就在悲傷沼澤中。",
["Kill the Demon of the Orb, then speak with Tabetha."]="殺死寶珠之魔，然後與塔貝薩談壹談。",
["Let Jarkal borrow the necklace. In exchange, he will translate the journal for you."]="將項鏈借給加卡爾。作為交換，他將幫妳翻譯日記。",
["Listen as Kalaran Windblade tells his story."]="聽卡拉然·溫布雷講述他的故事。",
["Listen to Royal Historian Archesonus recant the history of Thaurissan."]="聽皇家歷史學家阿克瑟努斯講述索瑞森的歷史。",
["Listen to Thrall."]="聽薩爾講話。",
["Listen to what Tirion Fordring has to say."]="聽聽提裏奧·弗丁要說什麽。",
["Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff."]="在通靈學院找到詹迪斯·巴羅夫並打敗她。從她的屍體上找到卡斯迪諾夫的恐懼之袋，然後將其交給艾瓦·薩克霍夫。",
["Look for a valuable necklace within the Uldaman dig site and bring it back to Dran Droffers in Orgrimmar. The necklace may be damaged."]="在奧達曼挖掘場中尋找壹條珍貴的項鏈，然後將其交給奧格瑞瑪的德蘭·杜佛斯。項鏈有可能已經損壞。",
["Master Apothecary Faranell in the Undercity wants 20 Hearts of Zeal."]="幽暗城的大藥劑師法拉尼爾需要20顆狂熱之心。",
["Motley Garmason at Dun Modr wants you to kill 10 Dark Iron Dwarves, 5 Dark Iron Tunnelers, 5 Dark Iron Saboteurs and 5 Dark Iron Demolitionists."]="丹莫德的莫特雷·加瑪森要求妳殺死15名黑鐵矮人、5名黑鐵隧道工、5名黑鐵破壞者和5名黑鐵爆破手。",
["Motley Garmason wants Kam Deepfury's head brought to him at Dun Modr."]="丹莫德的莫特雷·加瑪森要求妳把卡姆·深怒的頭顱交給他。",
["Nalpak in the Wailing Caverns wants 20 Deviate Hides."]="哀嚎洞穴的納爾帕克想要20張變異皮革。",
["Nikova Raskol of Stormwind wants you to collect 10 Red Wool Bandanas."]="暴風城的尼科瓦·拉斯克要妳取得10條紅色毛紡面罩。",
["Obtain 4 Young Crocolisk Skins for James Halloran in Menethil Harbor."]="為米奈希爾港口的詹姆斯·哈洛蘭帶回4張小鱷魚皮。",
["Obtain a power source from the most powerful construct you can find in Uldaman, and deliver it to Talvash del Kissel in Ironforge."]="從奧達曼最強大的石人身上獲得能量源，然後將其交給鐵爐堡的塔瓦斯德。",
["Open the chest."]="打開箱子。",
["Place Dawn's Gambit in the Viewing Room of the Scholomance. Defeat Vectus, then return to Betina Bigglezink."]="將黎明先鋒放在通靈學院的觀察室裏。打敗維克圖斯，然後回到貝蒂娜·比格辛克那裏去。",
["Place the Essence of Eranikus in the Essence Font located in this lair in the Sunken Temple."]="把伊蘭尼庫斯精華放在精華之泉裏，精華之泉就在沈沒的神廟中，伊蘭尼庫斯的巢穴裏。",
["Purchase Xorothian Stardust from Ur'dan. Bring it to Gorzeeki Wildeyes in the Burning Steppes."]="從烏爾丹那裏購買克索諾斯星塵，把它交給燃燒平原的戈瑟奇·邪眼。",
["Read Baelog's Journal, explore the hidden chamber, then report to Prospector Stormpike."]="閱讀巴爾洛戈的日記，探索密室，然後向鐵爐堡的勘察員塔伯斯·雷矛匯報。",
["Read Henrig Lonebrow's Journal."]="閱讀亨裏格·獨眉的日記。",
["Read Mor'zul's Instructions. Summon a Xorothian Dreadsteed, defeat it, then bind its spirit to you."]="閱讀莫蘇爾的指南，並召喚出壹匹克索諾斯恐懼戰馬，擊敗它，然後控制它的靈魂。",
["Read Warosh's Scroll. Bring Warosh's Mojo to Warosh."]="閱讀瓦羅什的卷軸。將瓦羅什的蟑螂交給他。",
["Read from the Tablet of Theka to learn the name of the Witherbark spider god, then return to Master Gadrin."]="閱讀塞卡石板，了解枯木巨魔的蜘蛛之神的名字，然後回到加德林大師那裏。",
["Read the Pariah's Instructions. Afterwards, obtain the Amulet of Union from Maraudon and return it to the Centaur Pariah in southern Desolace."]="閱讀賤民的指引，然後從瑪拉頓得到聯合墜飾，將其交給淒涼之地南部的半人馬賤民。",
["Recover 10 Plagued Flesh Samples from Stratholme and return them to Betina Bigglezink. You suspect that any creature in Stratholme would have said flesh sample."]="從斯坦索姆找回20個瘟疫肉塊，並把它們交給貝蒂娜·比格辛克。妳覺得斯坦索姆中的生靈都不大可能長著肉……",
["Report back to Tonga Runetotem with your findings."]="向圖加·符文圖騰報告妳的發現。",
["Retrieve 4 Miners' Union Cards and return them to Wilder Thistlenettle in Stormwind."]="給暴風城的維爾德·薊草帶回4張礦業工會會員卡。",
["Retrieve Mythology of the Titans from the Monastery and bring it to Librarian Mae Paledust in Ironforge."]="從修道院拿回《泰坦神話》，把它交給鐵爐堡的圖書館員麥伊·蒼塵。",
["Retrieve a Putrid Vine from the guardian at the bottom of the Sunken Temple and return to Torwa Pathfinder."]="從沈沒的神廟底部的守衛身上得到壹些腐爛藤蔓，把它們交給托爾瓦·尋路者。",
["Retrieve an Obsidian Power Source and bring it to Tabetha in Dustwallow Marsh."]="找到壹個黑曜石能量源，將其交給塵泥沼澤的塔貝薩。",
["Retrieve the Arcane Shard from Morphaz and return to Archmage Xylem."]="從摩弗拉斯身上取回奧術碎片，然後返回大法師克希雷姆那兒。",
["Retrieve the Compendium of the Fallen from the Monastery in Tirisfal Glades and return to Sage Truthseeker in Thunder Bluff."]="從血色修道院裏找到《墮落者綱要》，把它交給雷霆崖的聖者圖希克。",
["Retrieve the Gnoam Sprecklesprocket from the Deadmines and return it to Shoni the Shilent in Stormwind."]="從死亡礦井中帶回小型高能發動機，將其帶給暴風城矮人區中的沈默的舒尼。",
["Retrieve the Sealed Azure Bag from the Timbermaw Shaman in Azshara. Then take the bag to Archmage Xylem, also found in Azshara."]="從艾薩拉的木喉薩滿祭司那兒取回密封的藍袋子，將它交給艾薩拉的大法師克希雷姆。",
["Retrieve the Stone Circle from Marvon Rivetseeker's workshop in Ratchet."]="到棘齒城去，從瑪爾馮·瑞文斯克的車間裏取回石環。",
["Return Foror's Compendium of Dragon Slaying to the Athenaeum."]="將《弗洛爾的屠龍技術綱要》還回圖書館。",
["Return Vorrel Sengutz's wedding ring to Monika Sengutz in Tarren Mill."]="把沃瑞爾·森加斯的結婚戒指還給塔倫米爾的莫尼卡·森古特斯。",
["Return the Azure Key to Lord Jorach Ravenholdt."]="將碧藍鑰匙交給喬拉齊·拉文霍德公爵。",
["Return the Exorcism Censer to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."]="把驅魔香爐交給暴風城教堂區的格雷森·沙東布瑞克公爵。",
["Return the book to its rightful owners."]="將這本典籍交給它的主人。",
["Return to Fel'Zerul in Stonard."]="向斯通納德的費澤魯爾回報。",
["Return to Ironforge and deliver the bad news to King Magni Bronzebeard."]="回到鐵爐堡，把這個壞消息帶給國王麥格尼·銅須。",
["Return to Magistrate Marduke in Caer Darrow. Show him the Soulbound Keepsake."]="回到凱爾達隆的馬杜克鎮長那裏，把禁錮靈魂的遺物交給他。",
["Return to Mux Manascrambler in Gadgetzan with 1 Delicate Arcanite Converter, 4 Greater Eternal Essence, 10 Stonescale Oil, 25 Volcanic Ash and 40 gold."]="將1個精密奧金轉換器、4份強效不滅精華、10瓶石鱗魚油、25份火山灰和40枚金幣交給加基森的穆克斯·瑪納斯卡波。",
["Return to Tonga at The Crossroads, after investigating the Stagnant Oasis."]="調查死水綠洲，然後返回十字路口向圖加·符文圖騰報告。",
["Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!"]="返回圖書館去找到辛德拉的寶藏。拿取妳的獎勵吧！",
["Return with the Blessed Arcanite Barding to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."]="將被祝福的奧金馬鎧交給暴風城教堂區的格雷森·沙東布瑞克公爵。",
["Rhapsody Shindigger in The Hinterlands wants you to bring him 3 Roc Gizzards, 3 Groddoc Livers and 3 Ironfur Livers."]="辛特蘭的拉普索迪·鐵鏟要求妳帶給他3塊大鵬的砂囊、3塊格羅多克猩猩的肝臟和3塊鐵鬃熊的肝臟。",
["Scout Riell at the Sentinel Hill Tower wants you to bring her 10 Red Silk Bandanas."]="給哨兵嶺哨塔的哨兵瑞爾帶回10條紅色絲質面罩。",
["Search Dire Maul for Kariel Winthalus. Report back to Sage Korolusk at Camp Mojache with whatever information that you may find."]="到厄運之槌去尋找卡裏爾·溫薩魯斯。向莫沙徹營地的先知科魯拉克報告妳所找到的信息。",
["Search Dire Maul for Kariel Winthalus. Report back to Scholar Runethorn at Feathermoon with whatever information that you may find."]="到厄運之槌去尋找卡裏爾·溫薩魯斯。向羽月要塞的學者盧索恩·紋角報告妳所找到的信息。",
["Search Orgrimmar for Ragefire Chasm, then kill 8 Ragefire Troggs and 8 Ragefire Shaman before returning to Rahauro in Thunder Bluff."]="在奧格瑞瑪找到怒焰裂谷，殺掉8個怒焰穴居人和8個怒焰薩滿祭司，然後向雷霆崖的拉哈羅復命。",
["Search Ragefire Chasm for Maur Grimtotem's corpse and search it for any items of interest."]="在怒焰裂谷搜尋瑪爾·恐怖圖騰的屍體以及他留下的東西。",
["Search for an imp inside a cave at the entrance of Darkwhisper Gorge in southern Winterspring, purchase a Fel Elemental Rod and return to Mux Manascrambler in Gadgetzan."]="前往冬泉谷南方的暗語峽谷入口，向住在洞穴裡的小鬼買下一把惡魔元素魔棒，再回到加基森的莫克斯·法力爭奪者那裡。",
["Search for clues as to the current disposition of Talvash's necklace within Uldaman. The slain paladin he mentioned was the person who had it last."]="去奧達曼尋找塔瓦斯的魔法項鏈，被殺的聖騎士是最後壹個拿著它的人。",
["Search for the original creator of the shattered necklace to learn of its potential value."]="找到破碎的項鏈的來源，從而了解其潛在的價值。",
["Seek out Argent Guard Thaelrid in Blackfathom Deeps."]="到黑色深淵去找到銀月守衛塞爾瑞德。",
["Seek out Commander Ashlam Valorfist. His base camp is located at Chillwind Camp, north of the Alterac Mountains."]="找到指揮官阿什拉姆·瓦羅菲斯特。他的大本營位於奧特蘭克山脈以北的冰風崗。",
["Seek out High Executor Derrington. His base camp is located at the Bulwark, east of Tirisfal Glade and the Undercity."]="找到高級執行官德靈頓。他將自己的大本營建在提瑞斯法林地和幽暗城以東的亡靈壁壘。",
["Seek out Ogtinc in Azshara."]="找到艾薩拉的奧汀克。",
["Seek out Remulos in Moonglade and give him the Seed of Life."]="到月光林地去找到雷姆洛斯，將生命之種交給他。",
["Seek out Rexxar. The Warchief has instructed you as to his whereabouts. Search the paths of Desolace, between the Stonetalon Mountains and Feralas."]="按照酋長的指示找到雷克薩。他在石爪山和菲拉斯之間的淒涼之地遊蕩。",
["Seek out Rhapsody Shindigger in The Hinterlands."]="去辛特蘭找到拉普索迪·鐵鏟。",
["Seek out Sanath Lim-yo and gain passage to see Archmage Xylem."]="找到薩納斯，讓他將妳傳送到大法師克希雷姆那兒。",
["Slaughter the Shadowsworn in the Blasted Lands and return to the Fallen Hero of the Horde."]="殺死詛咒之地的魔誓者，然後回到部落英雄的靈魂那兒。",
["Slay 15 Black Broodlings, 10 Black Dragonspawn, 4 Black Wyrmkin and 1 Black Drake. Return to Helendis Riverhorn when the task is complete."]="殺掉15條黑色小龍、10條黑色龍人和1條黑色幼龍。當妳完成任務之後就向赫林迪斯·河角回報。",
["Slay 20 Plaguehound Runts, 5 Plaguehounds and 5 Frenzied Plaguehounds. Return to Tirion Fordring when the task is complete."]="殺掉20條瘟疫幼犬、5條瘟疫犬和5條狂怒的瘟疫犬。任務完成之後向提裏奧·弗丁復命。",
["Slay 30 Plaguebats and return to Tirion Fordring."]="殺死30只瘟疫蝙蝠，然後向提裏奧·弗丁復命。",
["Slay Fineous Darkvire and recover the great hammer, Ironfel. Take Ironfel to the Shrine of Thaurissan and place it on the statue of Franclorn Forgewright."]="殺掉弗諾斯·達克維爾並拿回戰錘鐵膽。把鐵膽之錘拿到索瑞森神殿去，將其放在弗蘭克羅恩·鑄鐵的雕像上。",
["Slay Halycon, pack mistress of the Bloodaxe worg."]="殺死血斧座狼的領袖，哈雷肯。",
["Slay Highlord Omokk, War Master Voone, and Overlord Wyrmthalak. Recover Important Blackrock Documents. Return to Warlord Goretooth in Kargath when the mission has been accomplished."]="殺死歐莫克大王、指揮官沃恩和維姆薩拉克。找到重要的黑石文件，然後向卡加斯的軍官高圖斯匯報。",
["Slay Princess Theradras and return to Keeper Marandis at Nijel's Point in Desolace."]="殺死瑟萊德絲公主，然後回到淒涼之地尼耶爾前哨站的守護者瑪蘭迪斯那裏復命。",
["Slay Princess Theradras and return to Selendra near Shadowprey Village in Desolace."]="殺死瑟萊德絲公主，然後回到淒涼之地葬影村附近的瑟琳德拉那裏復命。",
["Speak to Commander Ashlam Valorfist at Chillwind Camp."]="與冰風崗的指揮官阿什拉姆·瓦羅菲斯特談壹談。",
["Speak to Dorn Plainstalker in Thousand Needles."]="和千針石林的多恩·平原行者談壹談。",
["Speak to Duthorian Rall in Stormwind."]="與暴風城的達索瑞恩·拉爾談壹談。",
["Speak to Historian Karnik."]="和史學家卡尼克談壹談。",
["Speak to Je'neu Sancrea in Ashenvale."]="與灰谷的耶努薩克雷談壹談。",
["Speak to Jordan Stilwell in Ironforge"]="去和鐵爐堡的喬丹·斯迪威爾談壹談。",
["Speak to Ogtinc in Azshara."]="跟艾薩拉的奧汀克談壹談。",
["Speak with Alchemist Arbington at Chillwind Point, Western Plaguelands."]="和西瘟疫之地冰風崗的化學家阿爾比頓談壹談。",
["Speak with Apothecary Dithers at the Bulwark, Western Plaguelands."]="和西瘟疫之地亡靈壁壘的藥劑師迪瑟斯談壹談。",
["Speak with Brother Anton in Desolace."]="與淒涼之地的安東修士談壹談。",
["Speak with Franclorn Forgewright if you are interested in obtaining a key to the city major."]="如果妳想要得到進入這座城市主城區的鑰匙，就去和弗蘭克羅恩·鑄鐵談壹談。",
["Speak with Grimand Elmore in Stormwind's Dwarven District."]="與暴風城矮人區的格瑞曼德·艾爾默談壹談。",
["Speak with Gryphon Master Talonaxe inside the Aerie Peak Aviary."]="與辛特蘭的鷹巢山獅鷲飼養場裏的獅鷲管理員沙拉克·鷹斧談壹談。",
["Speak with Hamuul Runetotem."]="和哈繆爾·符文圖騰談壹談。",
["Speak with High Thane Falstad Wildhammer at Aerie Peak in the Hinterlands."]="找到辛特蘭的弗斯塔德·蠻錘。",
["Speak with Highlord Bolvar Fordragon after speaking with Lady Katrana Prestor."]="與女伯爵卡特拉娜·普瑞斯托談話，然後再與伯瓦爾·弗塔根公爵談話。",
["Speak with Jaron Stoneshaper in Starfall Village."]="與墜星村的加隆·石矛談壹談。",
["Speak with Klockmort Spannerspan in Ironforge."]="與鐵爐堡的科勞莫特·鋼尺談壹談。",
["Speak with Latronicus Moonspear at the Feathermoon Stronghold in Feralas."]="和菲拉斯羽月要塞的拉托尼庫斯·月矛談壹談。",
["Speak with Lord Grayson Shadowbreaker in Stormwind's Cathedral District."]="與暴風城教堂區的格雷森·沙東布瑞克公爵談壹談。",
["Speak with Lord Jorach Ravenholdt in Ravenholdt Manor."]="前往拉文霍德莊園，和喬拉齊·拉文霍德公爵談壹談。",
["Speak with Marshal Maxwell in the Burning Steppes."]="和燃燒平原的麥克斯韋爾元帥談壹談。",
["Speak with Master Gadrin in Sen'jin Village."]="與森金村的加德林大師談壹談。",
["Speak with Master Mechanic Castpipe in Ironforge."]="與鐵爐堡的大機械師卡斯派普談壹談。",
["Speak with Mayara Brightwing in the Burning Steppes."]="與燃燒平原的瑪亞拉·布萊特文談壹談。",
["Speak with Mor'zul Bloodbringer in the Burning Steppes."]="與燃燒平原的莫蘇爾·召血者談壹談。",
["Speak with Nara Wildmane."]="和納拉·蠻鬃談壹談。",
["Speak with Ozzie Togglevolt in Kharanos."]="與卡拉諾斯的奧齊·電環談壹談。",
["Speak with Prospector Ironband at Ironband's Excavation Site in Loch Modan."]="和洛克莫丹鐵環挖掘場的勘察員基恩薩·鐵環談壹談。",
["Speak with Ragnar Thunderbrew."]="和拉格納·雷酒談壹談。",
["Speak with Scooty in Booty Bay."]="和藏寶海灣的斯庫提談壹談。",
["Speak with Shadowmage Vivian Lagrave."]="與卡加斯的暗法師薇薇安·拉格雷談壹談。",
["Speak with Shadowmaster Vivian Lagrave in Kargath."]="與卡加斯的暗法師薇薇安·拉格雷談壹談。",
["Speak with Squire Maltrake."]="與侍衛瑪特拉克談壹談。",
["Speak with Tabetha in Dustwallow Marsh."]="與塵泥沼澤的塔貝薩談壹談。",
["Speak with Tabetha."]="和塔貝薩談壹談。",
["Speak with Talo Thornhoof at Camp Mojache in Feralas."]="和菲拉斯莫沙徹營地的塔羅·刺蹄談壹談。",
["Speak with Thrall if you are prepared to take on the mission he has planned."]="如果妳準備好要接受薩爾所安排的任務，就去找他談壹談。",
["Speak with Tinkmaster Overspark in Ironforge."]="與鐵爐堡的工匠大師歐沃斯巴克談壹談。",
["Speak with Torwa Pathfinder in Un'Goro Crater."]="與安戈洛環形山的托爾瓦·尋路者談壹談。",
["Speak with Tran'rek in Gadgetzan."]="與加基森的特蘭雷克談壹談。",
["Speak with Warden Thelwater in the Stockade."]="與監獄的典獄官塞爾沃特談壹談。",
["Speak with Wizzle Brassbolts in the Shimmering Flats."]="和閃光平原的維茲爾·銅栓談壹談。",
["Speak with Yuka Screwspigot in the Burning Steppes."]="與燃燒平原的尤卡·斯庫比格特談壹談。",
["Speak with stone watcher and learn what ancient lore it keeps. Once you have learned what lore it has to offer, activate the Discs of Norgannon."]="和石頭守護者交談，從他那裏了解更多古代的知識。壹旦妳了解到了所有的內容之後就激活諾甘農圓盤。",
["Speak with the Fallen Hero of the Horde at the entrance to the Blasted Lands."]="到詛咒之地的入口去，與部落英雄的靈魂談壹談。",
["Stab a Devilsaur with the Devilsaur Barb. Return to Torwa Pathfinder in Un'Goro Crater when you have completed this task."]="將魔暴龍之刺紮入壹只魔暴龍的體內。",
["Stoma the Ancient has asked that you bring him a Mature Black Dragon Sinew. Should you find this sinew, return it to Stoma in Felwood."]="費伍德森林的古樹斯托瑪要求妳帶給他壹塊成年黑龍的肌腱。",
["Take Brother Anton's Letter of Commendation to Raleigh the Devout in Southshore."]="將安東修士的表彰信帶給南海鎮的虔誠的萊雷恩。",
["Take General Drakkisath's Command to Marshal Maxwell in Burning Steppes."]="把達基薩斯將軍的命令交給燃燒平原的麥克斯韋爾元帥。",
["Take Hammertoe's Amulet to Historian Karnik in Ironforge."]="把鐵趾的護符交給鐵爐堡的史學家卡尼克。",
["Take Hammertoe's Amulet to Prospector Ryedol in the Badlands."]="把鐵趾的護符交給荒蕪之地的勘察員雷杜恩。",
["Take Shaw's report to Gryan Stoutmantle in Westfall."]="將肖爾的報告交給西部荒野的格裏安·斯托曼。",
["Take Wiley's Note to Gryan Stoutmantle in Westfall."]="將威利的便箋交給西部荒野的格裏安·斯托曼。",
["Take Wiley's Note to Mathias Shaw in Stormwind."]="將威利的便箋交給暴風城的馬迪亞斯·肖爾。",
["Take a Bloodpetal to Gregan Brewspewer in Feralas."]="把血瓣花交給菲拉斯的格雷甘·山酒。",
["Take the Grimtotem Satchel to Rahauro in Thunder Bluff."]="將恐怖圖騰背包交給雷霆崖的拉哈羅。",
["Take the Head of Balnazzar to Duke Nicholas Zverenhoff in the Eastern Plaguelands."]="將巴納紮爾的頭顱交給東瘟疫之地的尼古拉斯·瑟倫霍夫公爵。",
["Take the Head of Onyxia to Highlord Bolvar Fordragon in Stormwind."]="將奧妮克希亞的頭顱交給暴風城的伯瓦爾·弗塔根公爵。",
["Take the Head of Onyxia to Thrall in Orgrimmar."]="將奧妮克希亞的頭顱交給奧格瑞瑪的薩爾。",
["Take the Lieutenant's Insignia to Neeru Fireblade and speak to him. Gauge if he believes you are a member of the Burning Blade and then return to Thrall in Orgrimmar."]="將軍官的徽章交給尼爾魯·火刃並與他談壹談，看看他是否相信妳是火刃氏族中的壹員，然後回到奧格瑞瑪的薩爾那裏。",
["Take the Small Scroll to Varimathras in the Undercity."]="把小卷軸交給幽暗城的瓦裏瑪薩斯。",
["Take the Soulbound Keepsake to Leonid Barthalomew in Eastern Plaguelands."]="把禁錮靈魂的遺物交給東瘟疫之地的萊尼德·巴薩羅梅。",
["Take the Torch of Retribution."]="拿起懲戒火炬。",
["Take the miniature version of the Discs of Norgannon to the Explorers' League in Ironforge."]="把迷妳版的諾甘農圓盤帶到鐵爐堡的探險者協會去。",
["Take the miniature version of the Discs of Norgannon to the one of the sages in Thunder Bluff."]="把迷妳版的諾甘農圓盤帶到雷霆崖的賢者那裏。",
["Talk to Malyfous Darkhammer in Everlook."]="與永望鎮的瑪雷弗斯·暗錘談壹談。",
["The Atal'ai Exile in The Hinterlands wants the Head of Jammal'an."]="辛特蘭的阿塔萊流放者要妳給他帶回迦瑪蘭的頭。",
["Track down the Defias Messenger in Westfall and bring his message to Stoutmantle."]="追捕西部荒野的迪菲亞信使，並將他身上攜帶著的信件交給斯托曼。",
["Travel into the Sunken Temple and discover the secret hidden in the circle of statues."]="到沈沒的神廟去，揭開雕像群中隱藏的秘密。",
["Travel to Blackrock Depths and slay General Angerforge! Return to Warlord Goretooth when the task is complete."]="到黑石深淵去殺掉安格弗將軍！當任務完成之後向軍官高圖斯復命。",
["Travel to Blackrock Spire and collect 20 Black Dragonspawn Eyes. Return to Myranda the Hag when the task is complete."]="到黑石塔去收集20顆黑色龍人的眼球，完成任務之後回到巫女麥蘭達那裏。",
["Travel to Blackrock Spire and destroy War Master Voone, Highlord Omokk, and Overlord Wyrmthalak. Return to Marshal Maxwell when the job is done."]="到黑石塔去消滅指揮官沃恩、歐莫克大王和維姆薩拉克。完成任務之後回到麥克斯韋爾元帥處復命。",
["Travel to Blackrock Spire and destroy the source of the worg menace. As you left Helendis, he shouted a name: Halycon. It is what the orcs refer to in regards to the worg."]="到黑石塔去摧毀那裏的座狼源頭。當妳離開的時候，赫林迪斯喊出了壹個名字：哈雷肯。這個詞就是獸人語中“座狼”的意思。",
["Travel to Blackrock Spire and find Bloodaxe Worg Pups. Use the cage to carry the ferocious little beasts. Bring back a Caged Worg Pup to Kibler."]="到黑石塔去找到血斧座狼幼崽。使用籠子來捕捉這些兇猛的小野獸，然後把籠中的座狼幼崽交給基布雷爾。",
["Travel to Blackrock Spire and find out what happened to Bijou."]="到黑石塔去查明比修的下落。",
["Travel to Blackrock Spire and slay General Drakkisath. Gather his blood and return it to Rexxar."]="到黑石塔去殺掉達基薩斯將軍，把它的血交給雷克薩。",
["Travel to Blackrock Spire and slay Shadow Hunter Vosh'gajin. Recover Vosh'gajin's Snakestone and return to Kilram."]="到黑石塔去殺死暗影獵手沃什加斯，將沃什加斯的菊石交給基爾拉姆。",
["Travel to Blackrock Spire and slay Warchief Rend Blackhand. Take his head and return to Orgrimmar."]="去黑石塔殺死大酋長雷德·黑手，帶著他的頭顱返回奧格瑞瑪。",
["Travel to Gershala Nightwhisper in Auberdine."]="到奧伯丁的戈沙拉·夜語那兒去。",
["Travel to Grim Batol and track down Axtroz, drake champion of the Red Flight. Destroy him and take his skull. Return the skull to Emberstrife."]="到格瑞姆巴托去殺掉紅龍埃克托茲，把他的顱骨交給埃博斯塔夫。",
["Travel to Ironforge and get High Priest Rohan's Exorcism Censer. You will need to make a donation of 150 gold in order to secure it."]="到鐵爐堡去找高階牧師洛漢，從他那裏拿到驅魔香爐。妳需要捐贈150金幣來獲得它。",
["Travel to Lakeshire and deliver Helendis Riverhorn's Letter to Magistrate Solomon."]="把赫林迪斯·河角的信交給湖畔鎮的所羅門鎮長。",
["Travel to Light's Hope in Eastern Plaguelands and seek out Leonid Barthalomew the Revered. Show him the Keepsake of Remembrance and tell him all that you have discovered."]="到東瘟疫之地的聖光之願禮拜堂去找到萊尼德·巴薩羅梅，給他看看巫妖生前的遺物，並告訴他妳收集到的情報。",
["Travel to Marvon Rivetseeker's workshop in Ratchet."]="到棘齒城去，在瑪爾馮·瑞文斯克的車間裏找到他。",
["Travel to Northdale, in the northeastern region of the Eastern Plaguelands, and recover the Symbol of Lost Honor. Return to Tirion Fordring upon completion of your objective."]="到東瘟疫之地東北部的北谷去，找到失落榮耀的象征。完成目標之後向提裏奧·弗丁復命。",
["Travel to Silithus and search for a Reliquary of Purity within the ruins of Southwind Village. If you are able to find it, return with it to Rabine Saturna in Nighthaven, Moonglade."]="到希利蘇斯的南風村去尋找凈化之匣。然後將其交給月光林地永夜港的拉比恩·薩圖納。",
["Travel to Stormwind City and venture to the city gates. Speak with Squire Rowe so that he may let Marshal Windsor know that you have arrived."]="前往暴風城的城門。與侍衛洛文交談，他會通知溫德索爾元帥妳已經到達了。",
["Travel to Stratholme and find Archivist Galford of the Scarlet Crusade. Destroy him and burn down the Scarlet Archive."]="在斯坦索姆城中找到血色十字軍的檔案管理員加爾福特，殺掉他，然後燒毀血色十字軍檔案。",
["Travel to Stratholme and find Menethil's Gift. Place the Keepsake of Remembrance upon the unholy ground."]="到斯坦索姆城裏去找到米奈希爾的禮物，把巫妖生前的遺物放在那塊邪惡的土地上。",
["Travel to Stratholme and slay Ramstein the Gorger. Take his head as a souvenir for Nathanos."]="到斯坦索姆去，殺掉吞咽者拉姆斯登。把他的頭顱交給納薩諾斯。",
["Travel to Stratholme, in the north. Search the supply crates that litter the city and recover 5 Stratholme Holy Water. Return to Leonid Barthalomew the Revered when you have collected enough of the blessed fluid."]="到北方的斯坦索姆去，尋找散落在城市中的補給箱，並收集5瓶斯坦索姆聖水。當妳找到足夠的聖水之後就回去向萊尼德·巴薩羅梅復命。",
["Travel to Winterspring and find Haleh. Give her Awbee's scale."]="到冬泉谷去找到哈爾琳，把奧比的鱗片交給她。",
["Travel to island of Caer Darrow, in the south-central region of the Plaguelands, and look for any clues as to the whereabouts of the painting."]="到凱爾達隆島去，尋找關於那副畫的線索。凱爾達隆島在瘟疫之地南部的湖中央。",
["Travel to the Arathi Highlands, to the ruins of Stromgarde. Search Stromgarde for a Keepsake of Remembrance. If you find such an item, return with it to Magistrate Marduke."]="到阿拉希高地的激流堡遺跡裏面尋找巫妖生前的遺物。如果妳能找到這樣的東西，就把它交給馬杜克鎮長。",
["Travel to the Burning Steppes and give Bijou's Information to Marshal Maxwell."]="到燃燒平原去，把比修的情報交給麥克斯韋爾元帥。",
["Travel to the Undercroft - at the southernmost section of the Eastern Plaguelands - and recover Taelan's Hammer. Return to Tirion Fordring upon completion of your objective."]="到東瘟疫之地最南端的墓室去找回泰蘭之錘。完成目標之後，返回提裏奧·弗丁那裏。",
["Travel to the Warpwood Quarter of Dire Maul and slay the water elemental, Hydrospawn. Return to Lorekeeper Lydros in the Athenaeum with the Hydrospawn Essence."]="到厄運之槌的扭木廣場去殺掉水元素海多斯博恩。把海多斯博恩精華交給圖書館的博學者萊德羅斯。",
["Turn the Thorium Brotherhood Contract in to Lokhtos Darkbargainer if you would like to receive the plans for Sulfuron."]="如果妳願意接受薩弗隆的設計圖，請將瑟銀兄弟會契約交給羅克圖斯·暗契。",
["Use Jaron's Pick to find the four Highborne Relic Fragments. Bring them to Aurora Skycaller in Eastern Plaguelands."]="使用加隆的鎬來尋找四塊上層精靈遺物的碎片，把它們交給東瘟疫之地的奧蘿拉。",
["Use the Ectoplasmic Distiller near incorporeal undead to collect 12 Scorched Ectoplasms in Silithus, 12 Frozen Ectoplasms in Winterspring and 12 Stable Ectoplasms in the Eastern Plaguelands. Bring them along with the Ectoplasmic Distiller back to Mux Manascrambler in Gadgetzan."]="前往東瘟疫之地，在無形的不死族附近使用外膜蒸餾器收集12個希利蘇斯燒焦的外膜、12個冬泉谷冰凍的外膜和12個東瘟疫之地穩定的外膜。將它們和外膜蒸餾器一起交給在加基森的莫克斯·法力爭奪者。",
["Use the Eggscilloscope Prototype on an egg in the Rookery."]="在孵化間對著某顆龍蛋使用龍蛋冷凍器初號機。",
["Use the Empty Leaden Collection Phial on Irradiated Invaders or Irradiated Pillagers to collect radioactive fallout. Once it is full, take it back to Ozzie Togglevolt in Kharanos."]="用空鉛瓶對著輻射入侵者或者輻射搶劫者，從它們身上收集放射塵。瓶子裝滿之後，把它交給卡拉諾斯的奧齊·電環。",
["Use the Exorcism Censer to drive out the spirits that torment Terrordale. When you have slain 25 Terrordale Spirits, return to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."]="使用驅魔香爐召喚恐懼谷中的靈魂。當妳殺掉25個恐懼谷的靈魂之後，回到暴風城教堂區的格雷森·沙東布瑞克公爵那裏復命。",
["Use the Extra-Dimensional Ghost Revealer at the entrance to Stratholme and speak with the ghost of Anthion Harmon."]="在斯坦索姆的入口使用超空間鬼魂顯像機並和安希恩·哈莫的鬼魂談談。",
["Using Jordan's Weapon Notes, find some Whitestone Oak Lumber, Bailor's Refined Ore Shipment, Jordan's Smithing Hammer, and a Kor Gem, and return them to Jordan Stilwell in Ironforge."]="按照喬丹的武器材料單上的說明去尋找壹些白石橡木、精煉礦石、喬丹的鐵錘和壹塊科爾寶石，然後回到鐵爐堡去見喬丹·斯迪威爾。",
["Venture to Gnomeregan and kill Mekgineer Thermaplugg. Return to High Tinker Mekkatorque when the task is complete."]="到諾莫瑞根去殺掉麥克尼爾·瑟瑪普拉格。完成任務之後向大工匠梅卡托克報告。",
["Venture to the Molten Core entry portal in Blackrock Depths and recover a Core Fragment. Return to Lothos Riftwaker in Blackrock Mountain when you have recovered the Core Fragment."]="進入黑石深淵，在通往熔火之心的傳送門附近找到壹塊熔火碎片，然後回到黑石山脈的洛索斯·天痕那裏。",
["Venture to the Ruins of Thaurissan in the Burning Steppes and recover information from the Thaurissan Relics. Return to Royal Historian Archesonus when you have recovered the information."]="到燃燒平原的索瑞森廢墟中去，從索瑞森遺物上搜集信息。當妳收集到足夠的信息之後，就回到皇家歷史學家阿克瑟努斯那裏。",
["Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Alexi Barov when you have completed this task."]="到通靈學院中去取得巴羅夫家族的寶藏。這份寶藏包括四份地契：凱爾達隆地契、布瑞爾地契、塔倫米爾地契，還有南海鎮地契。完成任務之後就回到阿萊克斯·巴羅夫那兒去。",
["Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Weldon Barov when you have completed this task."]="到通靈學院中去取得巴羅夫家族的寶藏。這份寶藏包括四份地契：凱爾達隆地契、布瑞爾地契、塔倫米爾地契，還有南海鎮地契。完成任務之後就回到維爾頓·巴羅夫那兒去。",
["Wait for Scooty to calibrate the Goblin Transponder."]="等斯庫提調整好地精傳送器。",
["Warden Thelwater of Stormwind wants you to kill 10 Defias Prisoners, 8 Defias Convicts, and 8 Defias Insurgents in The Stockade."]="暴風城的典獄官塞爾沃特要求妳殺死監獄中的10名迪菲亞囚徒、8名迪菲亞罪犯和8名迪菲亞叛軍。",
["You may either keep the ring, or you may find the person responsible for the imprint and engravings on the inside of the band."]="妳要麽自己留著這枚戒指，要麽就按照戒指內側刻著的名字找到它的主人。",
["You may have just stumbled on to something that Marshal Windsor would be interested in seeing. There may be hope, after all."]="溫德索爾元帥也許會對妳手中的東西感興趣。畢竟，希望還沒有被完全扼殺。",
["You must retrieve the Blood of the Black Dragon Champion from General Drakkisath. Drakkisath can be found in his throne room behind the Halls of Ascension in Blackrock Spire."]="妳必須從達基薩斯將軍身上取回黑龍勇士之血，妳可以在黑石塔的晉升大廳後面的房間裏找到他。",
["You must search the world for a being capable of restoring the power to the Fragment of the Dragon's Eye. The only information you possess about such a being is that they exist."]="妳必須尋遍世界以找到壹種能恢復龍眼碎片的能量的生物。妳對這種生物的唯壹了解就是：他們確實存在。",
-- Try404 6.2.8 quest objectives; unknown proper names retained for client verification.
["Accompany Lumina Windsinger and help her escape Fenris Keep."]="陪同 Lumina Windsinger，幫助她逃離芬里斯城堡。",
["Acquire the Mana Sieve from within the temple in Shen'dralas and use it to collect Ancient Mana Crystals. Once you have acquired enough mana, empower the pylons and return to Mordent Evenshade."]="從 Shen'dralas 的神殿取得法力篩，收集遠古法力水晶。收集足夠法力後為水晶塔注能，並返回 Mordent Evenshade 身邊。",
["Bring 10 Motes of Unstable Magic to Archmage Celindra in Dalaran."]="將 10 份不穩定的魔法微粒交給達拉然的大法師 Celindra。",
["Bring 10 bottles of Silvermoon Shimmerwine to Arille Azuregaze in Dalaran city."]="將 10 瓶銀月微光酒交給達拉然城的 Arille Azuregaze。",
["Bring Ott's Masterwork to Trevan Rol in Silverpine Forest."]="將奧特的傑作交給銀松森林的 Trevan Rol。",
["Bring Thermaplugg's Engineering Notes to Nogg at the Valley of Honor in Orgrimmar."]="將瑟瑪普拉格的工程學筆記交給奧格瑞瑪榮譽谷的諾格。",
["Bring the Blackfathom Pearl to Bashana Runetotem in Thunder Bluff."]="將黑暗深淵珍珠交給雷霆崖的 Bashana Runetotem。",
["Bring the Blackfathom Pearl to Dawnwatcher Selgorm in Darnassus."]="將黑暗深淵珍珠交給達納蘇斯的 Dawnwatcher Selgorm。",
["Bring the Head of the Baron to the body of Othmar in the Undercity."]="將男爵的頭顱帶到幽暗城 Othmar 的遺體旁。",
["Bring the Orders from the Grand Crusader back to Katherine the Pure."]="將大十字軍的命令帶回給純潔的 Katherine。",
["Bring the Satchel of Cursed Mementos to Ashe Amberhall in Farholde Keep."]="將詛咒紀念品袋交給 Farholde Keep 的 Ashe Amberhall。",
["Collect 'Rumi of Gnomeregan: The Collected Works' and bring it to Garion Wendell in Stormwind."]="收集《諾姆瑞根的魯米：作品集》，交給暴風城的 Garion Wendell。",
["Collect 5 I'lalai Fetishes from trolls in the Drowned City."]="從沉沒之城的巨魔身上收集 5 個 I'lalai 神像。",
["Collect 5 Twilight Pages from within Sunnyglade for Ashe Amberall in Farholde Keep."]="在 Sunnyglade 收集 5 頁暮光文稿，交給 Farholde Keep 的 Ashe Amberhall。",
["Collect 7 Gnomeregan Archival Data cards from around Gnomeregan, then deliver them to Jemma Quikswitch in Ironforge."]="在諾姆瑞根各處收集 7 張檔案資料卡，交給鐵爐堡的 Jemma Quikswitch。",
["Collect 8 Cultist Bangles from the Twilight's Hammer in Krol'dok Stronghold."]="從克羅多克要塞的暮光之錘成員身上收集 8 個信徒腕環。",
["Collect Skullthumper from Klunk for Clugfist in Bolder'ok."]="從 Klunk 處取得 Skullthumper，交給 Bolder'ok 的 Clugfist。",
["Collect a Toxic Skullcap from Tawny Grisette in the Trade Quarter, Blisterweed near the Herbalism Trainer, and Essence of Agony from the poison vendor in the Rogues' Quarter for Master Apothecary Faranell in Undercity."]="在貿易區向 Tawny Grisette 收集有毒的盔帽，在草藥學訓練師附近收集泡葉草，在盜賊區的毒藥商處取得痛苦精華，交給幽暗城的大藥劑師法拉尼爾。",
["Collect the Arcane Mote for the Image of Archmage Modera near the City of Dalaran."]="收集奧術微粒，交給達拉然城附近的大法師莫德拉的影像。",
["Convince a Twilight's Hammer miner in Sunnyglade to divulge their secrets."]="說服 Sunnyglade 的一名暮光之錘礦工透露秘密。",
["Defeat 8 Twilight Fanatics, 8 Twilight Corrupters, and 8 Twilight Champions within the Twilight's Shroud for Da'grosh."]="在 Twilight's Shroud 擊敗 8 名暮光狂熱者、8 名暮光腐蝕者和 8 名暮光勇士，向 Da'grosh 覆命。",
["Defeat 8 Twilight Fanatics, 8 Twilight Corrupters, and 8 Twilight Champions within the Twilight's Shroud for Sergeant Riftan."]="在 Twilight's Shroud 擊敗 8 名暮光狂熱者、8 名暮光腐蝕者和 8 名暮光勇士，向 Riftan 中士覆命。",
["Defeat 8 Twilight Raiders and 8 Twilight Neophytes within Sunnyglade for Tran'gul in Rog'mar."]="在 Sunnyglade 擊敗 8 名暮光襲擊者和 8 名暮光新兵，向 Rog'mar 的 Tran'gul 覆命。",
["Defeat Charlga Razorflank in Razorfen Kraul and collect information on the quilboar's plans."]="擊敗剃刀沼澤的卡爾加·刺肋，收集有關野豬人計劃的情報。",
["Defeat Overlord Kilgar within the Twilight's Shroud and bring his head to Da'grosh."]="在 Twilight's Shroud 擊敗霸主 Kilgar，並將他的頭顱交給 Da'grosh。",
["Defeat Overlord Kilgar within the Twilight's Shroud and bring his head to Sergeant Riftan."]="在 Twilight's Shroud 擊敗霸主 Kilgar，並將他的頭顱交給 Riftan 中士。",
["Deliver Chogg's head to the ogre city to the north."]="將 Chogg 的頭顱送到北方的食人魔城市。",
["Deliver the Abominable Head to Master Apothecary Faranell within the Undercity."]="將憎惡的頭顱交給幽暗城的大藥劑師法拉尼爾。",
["Deliver the head of Chogg to Tran'gul in Rog'mar."]="將 Chogg 的頭顱交給 Rog'mar 的 Tran'gul。",
["Deliver the missive to Krom'rosh at Rog'mar."]="將密信交給 Rog'mar 的 Krom'rosh。",
["Destroy 5 Twilight Ritual Circles found throughout the caves underneath Sunnyglade."]="摧毀 Sunnyglade 地下洞穴中的 5 個暮光儀式法陣。",
["Escort Sergeant Danneth out of the Serpent's Coil caves and back to Nethergarde Keep."]="護送 Danneth 中士離開 Serpent's Coil 洞穴，返回守望堡。",
["Explore Shen'dralas in an effort to find other pylons like the one you found."]="探索 Shen'dralas，尋找與之前發現的水晶塔相似的其他水晶塔。",
["Explore the Vile Reef and find the cavern entrance."]="探索 Vile Reef，尋找洞穴入口。",
["Find Da'grosh in the hills west of Rog'mar."]="在 Rog'mar 西邊的山丘尋找 Da'grosh。",
["Find Loremaster Dibbs in Southshore and bring him the Savage Coast Report Bundle."]="找到南海鎮的博學者迪布斯，將荊棘谷海岸報告交給他。",
["Find Sergeant Danneth somewhere in the Serpent's Coil caverns southeast of Nethergarde Keep."]="在守望堡東南方的 Serpent's Coil 洞穴尋找 Danneth 中士。",
["Find Sergeant Riftan near the Twilight's Shroud to the west."]="在西方 Twilight's Shroud 附近尋找 Riftan 中士。",
["Find The Horn of Xelthos inside of Shadowfang Keep. Then, return it to C's dead drop near Pyrewood Village."]="在影牙城堡找到 Xelthos 號角，然後將其放入焚木村附近 C 的秘密交接點。",
["Find The Talisman of Kazdor inside of Zul'Farrak. Then, bring it to Fahrad at Ravenholdt Manor. You must complete the job alone."]="在祖爾法拉克找到卡茲多爾護符，交給拉文霍德莊園的 Fahrad。你必須獨自完成任務。",
["Find Veyric Thundervein in Arathi Highlands."]="在阿拉希高地尋找 Veyric Thundervein。",
["Find Woodwyrd in the Forlorn Gardens at Shen'dralas in the Desolace."]="在淒涼之地 Shen'dralas 的荒棄花園尋找 Woodwyrd。",
["Find missing ogres in the caves beneath Sunnyglade for Clubtoe."]="在 Sunnyglade 地下洞穴尋找失蹤的食人魔，向 Clubtoe 覆命。",
["Find someone in Farholde Keep who may know about the mould."]="在 Farholde Keep 尋找可能知道模具下落的人。",
["Find someone in Rog'mar who may know about the mould."]="在 Rog'mar 尋找可能知道模具下落的人。",
["Find the missing Kor'kron Elites."]="找到失蹤的庫卡隆精英。",
["Find the owner of the Ancient Petrified Leaf. Good luck, <Name>; It's a big world."]="找到遠古石葉的主人。祝你好運，<Name>；世界很大。",
["Gather 10 Brinescale Tridents from Brinescale Skirmishers."]="從 Brinescale 散兵身上收集 10 把 Brinescale 三叉戟。",
["Inject the Hissing Serum into the system above Othmar's body for Master Apothecary Faranell."]="為大藥劑師法拉尼爾將嘶鳴血清注入 Othmar 遺體上方的裝置。",
["Investigate Fenris Isle to the east and learn the fate of the Earthen Ring traveling party."]="調查東面的芬里斯島，瞭解大地之環旅行隊的遭遇。",
["Investigate Fenris Keep to the north and attempt to locate the missing member of the Earthen Ring party."]="調查北面的芬里斯城堡，尋找失蹤的大地之環成員。",
["Investigate the Forlorn Gardens near Shen'dralas and then return to Mithera at the nearby temple."]="調查 Shen'dralas 附近的荒棄花園，然後回到附近神殿向 Mithera 覆命。",
["Kill 12 Fen Creepers, then return to Rethiel the Greenwarden in the Wetlands."]="擊殺 12 只沼澤爬行者，然後返回溼地向綠衣守護者 Rethiel 覆命。",
["Kill 15 Kurzen Jungle Fighters.  Return to Sergeant Yohwa at the Rebel Camp."]="擊殺 15 名庫爾森叢林戰士，然後回反抗軍營地向 Yohwa 中士覆命。",
["Kill 5 Empowered Brutes and 10 Twilight Ritualists then return to Clubtoe in Sunnyglade."]="擊殺 5 名強化蠻兵和 10 名暮光儀祭師，然後回 Sunnyglade 向 Clubtoe 覆命。",
["Kill 7 Twilight Maulers and 7 Twilight Firecallers for Clugfist in Bolder'ok."]="為 Bolder'ok 的 Clugfist 擊殺 7 名暮光鬥士和 7 名暮光喚火者。",
["Kill Chogg'Zac in the Sunnyglade cave and collect their heads for Clubtoe."]="在 Sunnyglade 洞穴擊殺 Chogg'Zac，收集他們的頭顱交給 Clubtoe。",
["Locate Magister Kirandis inside the temple of Shen'dralas."]="在 Shen'dralas 的神殿找到魔導師 Kirandis。",
["Log"]="日誌",
["Meet Sully McCleary in Dustwallow Marsh and learn more about your mission."]="在塵泥沼澤會見薩莉·麥克利裡，瞭解任務詳情。",
["Obtain a Necrotic Runestone from Maleki the Pallid in Stratholme, then find the Rotting Dwarf Corpse near the Undercroft in southwestern Eastern Plaguelands."]="從斯坦索姆的蒼白的瑪勒基處取得亡靈符文石，然後在東瘟疫之地西南部的墓穴附近尋找腐爛的矮人屍體。",
["Recover The Coldbringer's Eye from Razorfen Downs."]="從剃刀高地取回寒冰使者之眼。",
["Recover a Fragment of the Firelands from Blackrock Depths for Alaana Stormwalker in Mulgore."]="從黑石深淵取回火焰之地碎片，交給莫高雷的 Alaana Stormwalker。",
["Recover shards and fragments of the pylons, found guarded at the Magram and Gelkis villages. Return them to Mordent Evenshade."]="取回瑪格拉姆和吉爾吉斯村莊守衛的水晶塔碎片，交給 Mordent Evenshade。",
["Report to Krom'rosh in Rog'mar."]="向 Rog'mar 的 Krom'rosh 報到。",
["Report your findings to Master Apothecary Faranell in Undercity."]="向幽暗城的大藥劑師法拉尼爾報告調查結果。",
["Rescue 5 Farholde Scouts within the Twilight's Shroud for Sergeant Riftan."]="在 Twilight's Shroud 解救 5 名 Farholde 斥候，向 Riftan 中士覆命。",
["Rescue 5 Rog'mar Scouts within the Twilight's Shroud for Da'grosh."]="在 Twilight's Shroud 解救 5 名 Rog'mar 斥候，向 Da'grosh 覆命。",
["Retrieve 25 Twilight Charms from Twilight Shadowmancers and Twilight Neophytes in Sunnyglade for Ashe Amberhall in Farholde Keep."]="從 Sunnyglade 的暮光暗法師和暮光新兵身上取回 25 個暮光護符，交給 Farholde Keep 的 Ashe Amberhall。",
["Retrieve 3 Twilight Missives from Twilight Shadowmancers in Sunnyglade for Tran'gul in Rog'mar."]="從 Sunnyglade 的暮光暗法師身上取得 3 封暮光密信，交給 Rog'mar 的 Tran'gul。",
["Retrieve the Fenris Isle Key from the Rot Hide Gnolls and use it to free Lumina Windsinger."]="從腐皮豺狼人身上取得芬里斯島鑰匙，解救 Lumina Windsinger。",
["Return to Orphan Matron Aria in Dalaran and inform her of Sergeant Danneth's intentions to take in Randal."]="返回達拉然向孤兒監護人 Aria 說明 Danneth 中士打算收養 Randal。",
["Seek out a quilboar of significance at the Bristleback Retreat."]="在 Bristleback Retreat 尋找一位重要的野豬人。",
["Seek out the SI:7 agent stationed on Theramore Isle."]="尋找駐紮在塞拉摩島的軍情七處特工。",
["Slay 12 Meadowsbrook Farmhands, then return to Krom'rosh with news of your success."]="擊殺 12 名 Meadowsbrook 農場工人，然後向 Krom'rosh 覆命。",
["Slay 8 Farholde Priests and 12 Farholde Scouts south of the river."]="擊殺河流以南的 8 名 Farholde 牧師和 12 名 Farholde 斥候。",
["Slay Witch Doctor Zum'rah and bring Zum'rah's Head to Archmage Lan'dalock in Dalaran."]="擊殺巫醫祖穆拉恩，將他的頭顱交給達拉然的大法師蘭達洛克。",
["Slay Witch Doctor Zum'rah and bring Zum'rah's Head to Mazu'kon in Mulgore."]="擊殺巫醫祖穆拉恩，將他的頭顱交給莫高雷的 Mazu'kon。",
["Speak to Fahrad when you're ready to hear his plan."]="準備好聽取計劃時與 Fahrad 交談。",
["Speak to Mathrengyl Bearwalker at the Cenarion Enclave in Darnassus."]="與達納蘇斯塞納里奧區的 Mathrengyl Bearwalker 交談。",
["Speak with Deathguard Baldren about the mysterious Earthen Ring travelers who recently passed through The Sepulcher."]="向亡靈哨兵 Baldren 詢問最近經過瑟伯切爾的神秘大地之環旅人。",
["Speak with Katherine to learn more about Aeonas, and then find him in the Scarlet Monastery."]="與 Katherine 交談了解 Aeonas，然後在血色修道院找到他。",
["Speak with Lumina Windsinger in the Sepulcher."]="與瑟伯切爾的 Lumina Windsinger 交談。",
["Speak with Mordent Evenshade in Shen'dralas for information about the crystals you repaired."]="與 Shen'dralas 的 Mordent Evenshade 交談，瞭解你修復的水晶。",
["Speak with Ott and ask him to forge your blade."]="與奧特交談，請他鍛造你的劍。",
["Speak with Sergeant Danneth at Nethergarde Keep."]="與守望堡的 Danneth 中士交談。",
["Speak with Sergeant Ulka to learn more about the situation on Alcaz Isle."]="與烏爾卡中士交談，瞭解奧卡茲島的情況。",
["Speak with Trevan Rol in the Sepulcher and bring him the materials he requires."]="與瑟伯切爾的 Trevan Rol 交談，並帶給他所需材料。",
["Steal 6 Feed Satchels from the Alliance farm in Meadowsbrook then return to Krom'rosh."]="從 Meadowsbrook 的聯盟農場偷取 6 個飼料袋，然後返回 Krom'rosh 處。",
["Summon a Twilight's Thrall from a conduit within the Twilight Shroud and capture it with Amberhall's Soulstone."]="從 Twilight Shroud 的導管召喚一個暮光僕從，用 Amberhall 的靈魂石捕獲它。",
["Travel to Blackrock Mountain in the northwest and enter Blackrock Depths. Find out what became of Marshal Windsor.  You recall Ragged John talking about Windsor being dragged off to a prison."]="前往西北方黑石山並進入黑石深淵，查明溫德索爾元帥的下落。你記得 Ragged John 說過溫德索爾被拖進了監獄。",
["Travel to Dire Maul in Feralas and recover 15 Satyr Blood from the Wildspawn Satyr that inhabit the Warpwood Quarter. Return to Daio in the Tainted Scar when this is done. "]="前往菲拉斯的厄運之槌，從扭木區的 Wildspawn 薩特身上取得 15 份薩特之血，然後返回腐爛之痕向 Daio 覆命。",
["Travel to Dire Maul to acquire a Felvine Seed from Alzzin the Wildshaper, an Ancient Memento from Prince Tortheldrin, and an Earthstone Diamond Pinky Ring from King Gordok, and bring them to Pix Xizzix in Booty Bay."]="前往厄運之槌，從奧茲恩處取得魔藤種子，從託塞德林王子處取得遠古紀念品，從戈多克大王處取得土鑽指環，交給藏寶海灣的 Pix Xizzix。",
["Travel to Nethergarde Keep in the Blasted Lands and locate Sergeant Danneth."]="前往詛咒之地的守望堡，找到 Danneth 中士。",
["Travel to The Sepulcher in Silverpine Forest and speak with Trevan Rol about the missing Earthen Ring travelers."]="前往銀松森林的瑟伯切爾，與 Trevan Rol 交談，詢問失蹤的大地之環旅人。",
["Travel to the quarry in Blackrock Mountain and slay Overmaster Pyron. Return to Thunderheart when you have completed this assignment. "]="前往黑石山的採石場擊殺 Pyron，完成後向 Thunderheart 覆命。",
["Use the SI:7 Disguise Kit to eavesdrop on Jaina and her inner circle at the Theramore Mage Tower."]="使用軍情七處偽裝工具，在塞拉摩法師塔竊聽吉安娜和她的親信。",
["Use the hide and charcoal to create a rubbing of the Third Troll Legend tablet."]="使用皮革和木炭拓印第三塊巨魔傳說石板。",
["Use the hide and charcoal to create rubbings of the tablets found in the Drowned City."]="使用皮革和木炭拓印沉沒之城的石板。",
["Venture to Maraudon and recover a Vial of Earth Song Water and return it to Woodwyrd at the Forlorn Gardens in Desolace."]="前往瑪拉頓取回一瓶大地之歌之水，交給淒涼之地荒棄花園的 Woodwyrd。",
["Venture to Razorfen Downs and acquire Virulent Blood of Agamaggan, then return it to Kog'thug the Brave at Bristleback Retreat in the Desolace. Kog'thug felt it worth reminding that the Blood of Agamaggan inside Razorfen Kraul would not be sufficient."]="前往剃刀高地取得阿迦瑪甘的惡毒之血，交給淒涼之地 Bristleback Retreat 的 Kog'thug。剃刀沼澤中的阿迦瑪甘之血不能代替。",
["Watch as Ott forges your blade."]="觀看奧特鍛造你的劍。",
