["When struck by a harmful spell, has a 7% chance of Silencing the caster for 3 sec. Can only occur once every 60 sec. (Proc chance: 7%, 1m cooldown)"]="當受到有害法術攻擊時，有 7% 的機率使施法者沉默 3 秒。每 60 秒只能發生一次。 (觸發機率：7%，1m冷卻時間)",
["When struck in combat has a 2% chance of causing the attacker to flee in terror for 2 sec. Can only occur once every 60 sec. (Proc chance: 2%, 1m cooldown)"]="在戰鬥中被擊中時，有 2% 的機率導致攻擊者驚恐逃跑 2 秒。每 60 秒只能發生一次。 (觸發機率：2%，1m冷卻時間)",
["When struck in combat has a 2% chance of freezing the attacker in place for 3 sec. Can only occur once every 60 sec. (Proc chance: 2%, 1m cooldown)"]="在戰鬥中被擊中時，有 2% 的機率將攻擊者凍結在原地 3 秒。每 60 秒只能發生一次。 (觸發機率：2%，1m冷卻時間)",
["When struck in combat has a 2% chance of shielding the wearer in a protective shield which will absorb 488 damage. Can only occur once every 60 sec. (Proc chance: 2%, 1m cooldown)"]="當在戰鬥中被擊中時，有 2% 的機率用防護罩保護佩戴者，該防護罩將吸收 488 傷害。每 60 秒只能發生一次。 (觸發機率：2%，1m冷卻時間)",
["When struck in combat has a chance of returning 300 mana, 10 rage, or 40 energy to the wearer. (Proc chance: 2%)"]="在戰鬥中被擊中時，有機率將 300 法力、10 怒氣或 40 能量返回給佩戴者。 (觸發機率：2%)",
["When struck in combat, has a 10% chance to remove a Disarm effect from yourself. Can only occur once every 60 sec. (Proc chance: 10%, 1m cooldown)"]="在戰鬥中被擊中時，有 10% 的機率消除自己的繳械效果。每 60 秒只能發生一次。 (觸發機率：10%，1m冷卻時間)",
["When struck in combat, has a 5% chance to increase your movement speed by 10% for 8 sec. Can only occur once every 60 sec. (Proc chance: 5%, 1m cooldown)"]="在戰鬥中被擊中時，有 5% 的機率使你的移動速度提高 10%，持續 8 秒。每 60 秒只能發生一次。 (觸發機率：5%，1m冷卻時間)",
["When struck in combat, has a 5% chance to remove a Snare effect from yourself. Can only occur once every 60 sec. (Proc chance: 5%, 1m cooldown)"]="在戰鬥中被擊中時，有 5% 的機率消除自己的圈套效果。每 60 秒只能發生一次。 (觸發機率：5%，1m冷卻時間)",
["When struck in combat, has a 8% chance to remove a Root effect from yourself. Can only occur once every 60 sec. (Proc chance: 8%, 1m cooldown)"]="在戰鬥中被擊中時，有 8% 的機率消除自己的定身效果。每 60 秒只能發生一次。 (觸發機率：8%，1m冷卻時間)",
["When struck in melee combat, has a 5% chance of Disarming the attacker for 4 sec. Can only occur once every 60 sec. (Proc chance: 5%, 1m cooldown)"]="在近戰戰鬥中被擊中時，有 5% 的機率解除攻擊者的武裝，持續 4 秒。每 60 秒只能發生一次。 (觸發機率：5%，1m冷卻時間)",
["When struck in melee there is a 50% chance you will Fade for 4 sec. (Proc chance: 50%, 5s cooldown)"]="當在近戰中被擊中時，你有 50% 的機率會消失 4 秒。 (觸發機率：50%，5的冷卻時間)",
["When you cast a Healing Wave or Lesser Healing Wave, there is a 25% chance the target also receives a free Lightning Shield that causes 50 Nature damage to attacker on hit. (Proc chance: 25%)"]="當你施放治療波或次級治療波時，目標還有 25% 的機率獲得免費的閃電護盾，對攻擊者造成 50 自然傷害。 （觸發機率：25%）",
["When your health drops below 20%, for the next 5 seconds healing spells cast on you help you to Cheat Death, increasing healing done by up to 160."]="當你的生命值低於 20% 時，在接下來的 5 秒內，對你施放的治療法術會幫助你欺騙死亡，將治療效果提高最多 160。",
