["You have a chance whenever you deal ranged damage to apply an Expose Weakness effect to the target. Expose Weakness increases the Ranged Attack Power of all attackers against that target by 450 for 7 sec."]="每當你造成遠端傷害時，你就有機會對目標施加暴露弱點效果。暴露弱點使所有攻擊者對該目標的遠端攻擊強度增加 450，持續 7 秒。",
["Your Backstab, Sinister Strike, and Hemorrhage critical hits cause you to regain 5 energy. (500ms cooldown)"]="你的背刺、險惡打擊和出血暴擊會讓你恢復 5 能量。 (500ms 冷卻時間)",
