["Your Flash of Light and Holy Light spells have a chance to imbue your target with Holy Power. (Proc chance: 10%)"]="你的聖光閃現和聖光法術有一定機率為你的目標註入神聖力量。 （觸發機率：10%）",
["Your Frostfire Bolt spell has a 10% increased chance to trigger Missile Barrage, gains 10% increased critical strike chance while your Combustion spell is active, and has a 10% increased chance to trigger Fingers of Frost."]="你的霜火箭法術觸發導彈彈幕的機率提高 10%，當你的燃燒法術啟用時暴擊機率提高 10%，並且觸發冰霜之指的機率提高 10%。",
["Your Greater Heals now have a heal over time component equivalent to a rank 5 Renew."]="您的強效治療現在具有相當於等級 5 更新的隨時間治療部分。",
["Your Healing Wave and Lesser Healing Wave spells have a chance to imbue your target with Totemic Power. (Proc chance: 10%)"]="你的治療波和次級治療波法術有一定機率為你的目標註入圖騰力量。 （觸發機率：10%）",
["Your Healing Wave will now jump to additional nearby targets. Each jump reduces the effectiveness of the heal by 80%, and the spell will jump to up to two additional targets."]="你的治療波現在會跳到附近的其他目標。每次跳躍都會使治療效果降低 80%，並且該法術最多會跳躍到兩個額外目標。",
