["Your Rejuvenation ticks have a chance to restore 60 mana, 8 energy, or 2 rage to your target."]="你的回春蜱有機會為你的目標恢復 60 法力、8 能量或 2 怒氣。",
["Your Shadow Bolts now have a chance to heal you for 270 to 330."]="你的暗影箭現在有機會治癒你 270 到 330。",
["Your attacks have a chance to increase your Attack Power by 40 and your healing spells have a chance to increase your Intellect by 20 for 15 sec. (Proc chance: 10%)"]="你的攻擊有機會使你的攻擊強度增加 40，你的治療法術有機會使你的智力增加 20，持續 15 秒。 (觸發機率：10%)",
["Your damage spells have a chance to cause your target to take up to 200 increased damage from subsequent spells. (Proc chance: 20%)"]="你的傷害法術有一定機率使你的目標因後續法術而受到最多 200 的傷害。 （觸發機率：20%）",
["Your damage spells have a chance to displace you, causing the next spell cast to generate no threat. (Proc chance: 15%)"]="你的傷害法術有機會取代你，導致下一次施放的法術不會產生任何威脅。 （觸發機率：15%）",
["Your finishing moves now refund 30 energy on a Miss, Dodge, Block, or Parry."]="現在，你的終結動作會在未擊中、閃避、格擋或招架時返還 30 能量。",
